import 'dart:async';
import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:webview_flutter/webview_flutter.dart';
import '../../../../core/state/app_state.dart';

Uri? courierReceiptUri(String? value) {
  final uri = Uri.tryParse(value ?? '');
  return uri != null && uri.scheme == 'https' && uri.host.isNotEmpty && uri.userInfo.isEmpty
      ? uri : null;
}

Future<void> openCourierPixReceipt(BuildContext context, String url) async {
  final uri = courierReceiptUri(url);
  if (uri == null) return;
  final account = AppState.instance.user?['id']?.toString();
  if (account == null || !AppState.instance.isCourier) return;
  await Navigator.of(context).push<void>(MaterialPageRoute(builder: (_) =>
    CourierPixReceiptPage(uri: uri, accountId: account)));
}

class CourierPixReceiptPage extends StatefulWidget {
  const CourierPixReceiptPage({super.key, required this.uri, required this.accountId});
  final Uri uri;
  final String accountId;
  @override
  State<CourierPixReceiptPage> createState() => _CourierPixReceiptPageState();
}

class _CourierPixReceiptPageState extends State<CourierPixReceiptPage> {
  WebViewController? _controller;
  Timer? _timeout;
  int _progress = 0;
  String? _error;
  bool get _sameAccount => AppState.instance.isCourier &&
      AppState.instance.user?['id']?.toString() == widget.accountId;
  bool get _supported => !kIsWeb && const [TargetPlatform.android, TargetPlatform.iOS]
      .contains(defaultTargetPlatform);

  @override
  void initState() {
    super.initState();
    if (_supported && _sameAccount) {
      unawaited(_initialize());
    } else {
      _error = 'O comprovante integrado está disponível no aplicativo Android e iPhone.';
    }
  }

  Future<void> _initialize() async {
    try {
      final controller = WebViewController();
      await controller.setJavaScriptMode(JavaScriptMode.unrestricted);
      await controller.setBackgroundColor(Colors.white);
      await controller.setNavigationDelegate(NavigationDelegate(
        onNavigationRequest: (request) {
          final next = courierReceiptUri(request.url);
          final sameHost = next?.host == widget.uri.host;
          final asaasOrigin = widget.uri.host == 'asaas.com' || widget.uri.host.endsWith('.asaas.com');
          final asaasTarget = next != null && (next.host == 'asaas.com' || next.host.endsWith('.asaas.com'));
          if (!_sameAccount || next == null || (!sameHost && !(asaasOrigin && asaasTarget))) {
            return NavigationDecision.prevent;
          }
          return NavigationDecision.navigate;
        },
        onProgress: (value) { if (mounted) setState(() => _progress = value); },
        onPageFinished: (_) { _timeout?.cancel(); if (mounted) setState(() => _progress = 100); },
        onWebResourceError: (error) {
          if (error.isForMainFrame != false) _showError();
        },
      ));
      if (!mounted || !_sameAccount) return;
      setState(() => _controller = controller);
      await _load();
    } catch (_) { _showError(); }
  }

  void _showError() {
    _timeout?.cancel();
    if (mounted) setState(() => _error = 'Não foi possível carregar o comprovante. Confira sua conexão e tente novamente.');
  }

  Future<void> _load() async {
    if (!_sameAccount || !mounted) return;
    setState(() { _error = null; _progress = 0; });
    _timeout?.cancel();
    _timeout = Timer(const Duration(seconds: 25), _showError);
    try { await _controller?.loadRequest(widget.uri); } catch (_) { _showError(); }
  }

  @override
  void dispose() { _timeout?.cancel(); super.dispose(); }

  @override
  Widget build(BuildContext context) => AnimatedBuilder(
    animation: AppState.instance,
    builder: (context, _) => Scaffold(
      backgroundColor: const Color(0xFFF5F8F7),
      appBar: AppBar(backgroundColor: Colors.white, foregroundColor: const Color(0xFF073D3B),
        surfaceTintColor: Colors.transparent, title: const Text('Comprovante Pix',
          style: TextStyle(fontSize: 18, fontWeight: FontWeight.w700))),
      body: SafeArea(child: !_sameAccount
        ? const Center(child: Text('Entre na sua conta para consultar o comprovante.'))
        : Column(children: [
          Container(width: double.infinity, padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 14),
            color: const Color(0xFFEAF5F0),
            child: const Row(children: [Icon(Icons.verified_outlined, color: Color(0xFF00615C), size: 20),
              SizedBox(width: 10), Expanded(child: Text('Documento da transferência',
                style: TextStyle(color: Color(0xFF00615C), fontWeight: FontWeight.w600)))])),
          if (_error == null && _progress < 100)
            LinearProgressIndicator(value: _progress == 0 ? null : _progress / 100,
              color: const Color(0xFF00615C), backgroundColor: const Color(0xFFEAF5F0)),
          Expanded(child: _error != null ? Center(child: SingleChildScrollView(
            padding: const EdgeInsets.all(28), child: Column(mainAxisSize: MainAxisSize.min, children: [
              const Icon(Icons.receipt_long_outlined, size: 42, color: Color(0xFF00615C)),
              const SizedBox(height: 16), Text(_error!, textAlign: TextAlign.center),
              if (_supported) ...[const SizedBox(height: 18), FilledButton(
                onPressed: () { if (_controller == null) { unawaited(_initialize()); } else { unawaited(_load()); } },
                child: const Text('Tentar novamente'))],
            ]))) : _controller == null ? const Center(child: CircularProgressIndicator())
              : WebViewWidget(controller: _controller!)),
        ])),
    ),
  );
}

import 'package:flutter/material.dart';
import 'courier_pix_receipt.dart';

class CourierWalletMovement extends StatelessWidget {
  const CourierWalletMovement({super.key, required this.entry, this.withdrawal});
  final Map<String, dynamic> entry;
  final Map<String, dynamic>? withdrawal;

  String _money(double value) {
    final parts = value.abs().toStringAsFixed(2).split('.');
    return 'R\$ ${parts[0].replaceAllMapped(RegExp(r'(\d)(?=(\d{3})+(?!\d))'), (m) => '${m[1]}.')},${parts[1]}';
  }
  String _date(dynamic value) {
    final date = DateTime.tryParse(value?.toString() ?? '')?.toLocal();
    if (date == null) return 'Data indisponível';
    String two(int n) => n.toString().padLeft(2, '0');
    return '${two(date.day)}/${two(date.month)}/${date.year} • ${two(date.hour)}:${two(date.minute)}';
  }

  @override
  Widget build(BuildContext context) {
    final amount = double.tryParse(entry['amount']?.toString() ?? '') ?? 0;
    final positive = amount >= 0;
    final reversal = entry['type'] == 'REVERSAL';
    final isWithdrawal = withdrawal != null && !reversal;
    final status = withdrawal?['status']?.toString() ?? '';
    final paid = isWithdrawal && status == 'PAID';
    final failed = isWithdrawal && const ['REJECTED', 'CANCELLED', 'CANCELED', 'FAILED'].contains(status);
    final pending = isWithdrawal && const ['PENDING', 'PROCESSING'].contains(status);
    final uri = courierReceiptUri(withdrawal?['receiptUrl']?.toString());
    final title = reversal ? 'Saldo devolvido' : isWithdrawal ? 'Saque Pix' : switch(entry['type']) {
      'DELIVERY_CREDIT' => 'Entrega concluída', 'BONUS_CREDIT' => 'Bônus recebido',
      'ADJUSTMENT_CREDIT' => 'Crédito na carteira', _ => 'Movimentação',
    };
    final label = reversal ? 'Devolvido à carteira' : paid ? 'Pago' : failed ? 'Encerrado'
      : pending ? 'Em processamento' : positive ? 'Entrada' : 'Saída';
    final tone = pending ? const Color(0xFFA16C15) : failed ? const Color(0xFF78858A)
      : const Color(0xFF08766A);
    const ink = Color(0xFF123B3A);
    return Container(margin: const EdgeInsets.only(bottom: 12), padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(20),
        border: Border.all(color: const Color(0xFFE1EBE7))),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Container(padding: const EdgeInsets.all(11),
            decoration: BoxDecoration(color: tone.withValues(alpha: .08), borderRadius: BorderRadius.circular(14)),
            child: Icon(reversal ? Icons.undo_rounded : isWithdrawal ? Icons.north_east_rounded
              : Icons.south_west_rounded, size: 20, color: tone)),
          const SizedBox(width: 12),
          Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(title, style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w700, color: ink)),
            const SizedBox(height: 4), Text(_date(entry['createdAt']),
              style: const TextStyle(fontSize: 11, height: 1.4, color: Color(0xFF768881))),
          ])),
        ]),
        const SizedBox(height: 16),
        Text('${positive ? '+' : '−'} ${_money(amount)}', style: TextStyle(
          fontSize: 26, fontWeight: FontWeight.w800, letterSpacing: -.8,
          color: positive ? const Color(0xFF08766A) : ink)),
        const SizedBox(height: 10),
        Container(padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
          decoration: BoxDecoration(color: tone.withValues(alpha: .07), borderRadius: BorderRadius.circular(30)),
          child: Text(label, style: TextStyle(color: tone, fontSize: 11, height: 1.4, fontWeight: FontWeight.w600))),
        if (paid) ...[
          const Padding(padding: EdgeInsets.only(top: 16, bottom: 6),
            child: Divider(height: 1, color: Color(0xFFEBF0ED))),
          if (uri != null) SizedBox(width: double.infinity, child: TextButton.icon(
            onPressed: () => openCourierPixReceipt(context, uri.toString()),
            style: TextButton.styleFrom(foregroundColor: const Color(0xFF00615C),
              alignment: Alignment.centerLeft, padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 0)),
            icon: const Icon(Icons.receipt_long_outlined, size: 19),
            label: const Text('Ver comprovante', style: TextStyle(fontWeight: FontWeight.w700)),
          )) else const Padding(padding: EdgeInsets.only(top: 8), child: Text(
            'Pagamento confirmado. Comprovante ainda não disponibilizado.',
            style: TextStyle(fontSize: 12, height: 1.5, color: Color(0xFF768881)))),
        ],
      ]),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:porto_prime/features/courier/presentation/widgets/courier_wallet_movement.dart';
import 'package:porto_prime/features/courier/presentation/widgets/courier_pix_receipt.dart';

void main() {
  final entry = <String, dynamic>{'type': 'WITHDRAWAL_DEBIT', 'amount': -50,
    'createdAt': '2026-11-01T12:00:00Z'};
  for (final status in ['PAID', 'PROCESSING', 'REJECTED']) {
    for (final width in [320.0, 390.0, 768.0]) {
      testWidgets('$status movement fits $width with large text', (tester) async {
        tester.view.physicalSize = Size(width, 900); tester.view.devicePixelRatio = 1;
        addTearDown(tester.view.resetPhysicalSize);addTearDown(tester.view.resetDevicePixelRatio);
        await tester.pumpWidget(MaterialApp(home: MediaQuery(
          data: MediaQueryData(size: Size(width, 900), textScaler: TextScaler.linear(2)),
          child: Scaffold(body: SingleChildScrollView(child: Padding(padding: const EdgeInsets.all(18),
            child: CourierWalletMovement(entry: entry, withdrawal: {
              'status': status, 'receiptUrl': 'https://sandbox.asaas.com/receipt/test',
            })))),
        )));
        expect(tester.takeException(), isNull);
        expect(find.text('Ver comprovante'), status == 'PAID' ? findsOneWidget : findsNothing);
      });
    }
  }
  testWidgets('reversal never displays a payment receipt', (tester) async {
    await tester.pumpWidget(MaterialApp(home: Scaffold(body: CourierWalletMovement(
      entry: {...entry, 'type': 'REVERSAL', 'amount': 50},
      withdrawal: {'status':'PAID','receiptUrl':'https://sandbox.asaas.com/receipt/test'},
    ))));
    expect(find.text('Saldo devolvido'), findsOneWidget);
    expect(find.text('Ver comprovante'), findsNothing);
  });
  testWidgets('paid without provider receipt has a clear fallback', (tester) async {
    await tester.pumpWidget(MaterialApp(home: Scaffold(body: CourierWalletMovement(
      entry: entry, withdrawal: {'status':'PAID'},
    ))));
    expect(find.text('Ver comprovante'), findsNothing);
    expect(find.text('Pagamento confirmado. Comprovante ainda não disponibilizado.'), findsOneWidget);
  });
  test('receipt rejects non HTTPS and URLs with credentials', () {
    for (final value in ['', 'http://asaas.com/a', 'javascript:alert(1)', 'https://user:pass@asaas.com/a']) {
      expect(courierReceiptUri(value), isNull);
    }
    expect(courierReceiptUri('https://sandbox.asaas.com/a'), isNotNull);
  });
}
